```javascript
const table = document.querySelector('.table');
let sortColumn = 0;
let sortOrder = 1; // 1 for ascending, -1 for descending

table.addEventListener('click', (event) => {
  if (event.target.tagName === 'TH') {
    const columnIndex = Array.from(event.target.parentNode.children).indexOf(event.target);
    const sortType = event.target.dataset.sort;

    if (columnIndex === sortColumn) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(sortColumn, sortOrder, sortType);
  }
});

function sortTable(column, order, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.children[column].textContent;
    const cellB = b.children[column].textContent;

    let comparison = 0;

    switch (sortType) {
      case 'number':
        comparison = Number(cellA) - Number(cellB);
        break;
      case 'date':
        comparison = new Date(cellA) - new Date(cellB);
        break;
      default: // string
        comparison = cellA.localeCompare(cellB);
        break;
    }

    return order * comparison;
  });

  // Clear the table body and re-append the sorted rows
  const tbody = table.querySelector('tbody');
  tbody.innerHTML = '';
  rows.forEach(row => tbody.appendChild(row));
}
```

