                if (loginResponse == "Password correct")
                {
                    writer.WriteLine("GTMP?");
                    writer.Flush();
                    string temperature = reader.ReadLine();
                    Console.WriteLine("Temperature: " + temperature);
                }

                // Logout
                writer.WriteLine("LOGOUT");
                writer.Flush();
                Console.WriteLine("Logout message: " + reader.ReadLine());
            }
        }
        catch (Exception e)
        {
            Console.WriteLine("Error: " + e.Message);
        }
    }
}
